        quantity = int(qty_text)
    except ValueError:
        raise Refusal("quantity %r is too large" % qty_text) from None
    if quantity < 1:
        raise Refusal("bad quantity %r (a whole number of one or more)" % qty_text)
    note = positionals[3] if len(positionals) == 4 else ""
    if "\n" in note or "\r" in note:
        raise Refusal("a note may not contain a line break")
    note = note.strip(" \t")
