        who = (list(movements) + [candidate])[bad]
        raise Refusal(
            "stock of %s would go below zero on %s" % (who.sku, who.date.isoformat())
        )
    line = "%s %s %+d%s" % (date.isoformat(), sku, delta, " " + note if note else "")
    _append(directory, existing, line + "\n")
    return line + "\n"


