                ln.quantity,
                _amount(ln.unit),
                _amount(ln.gross),
                _amount(ln.discount),
                _amount(ln.net),
            )
        )
    rows.append("subtotal " + _amount(quote.subtotal))
    rows.append("order discount " + _amount(quote.order_discount))
    rows.append("tax " + _amount(quote.tax))
    rows.append("total " + _amount(quote.total))
    return _lines(rows)


def _quote_json(order, quote):
    return _dump(
        {
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": ln.sku,
                    "quantity": ln.quantity,
                    "unit": _amount(ln.unit),
                    "gross": _amount(ln.gross),
                    "discount": _amount(ln.discount),
                    "net": _amount(ln.net),
                }
                for ln in quote.lines
            ],
            "subtotal": _amount(quote.subtotal),
            "order_discount": _amount(quote.order_discount),
            "tax": _amount(quote.tax),
            "total": _amount(quote.total),
        }
    )


def _find_order(orders, text):
    if ORDER_ID_RE.fullmatch(text):
        wanted = "SO-" + text[3:]
        for order in orders:
            if order.id == wanted:
                return order
    raise Refusal("unknown order %r" % text)


def _quote(catalog, orders, positionals, options, prefix=""):
    order = _find_order(orders, positionals[0])
    quote = price_order(order, catalog)
    if options["json"]:
        return _quote_json(order, quote)
    header = "%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)
    return _quote_text(quote, header)


def _invoice(catalog, movements, orders, positionals, options):
    order = _find_order(orders, positionals[0])
    shipped = orders_mod.invoice_order(order, movements)
    if shipped is None:
        raise Refusal("nothing has shipped for %s" % order.id)
    quote = price_order(shipped, catalog)
    if options["json"]:
        return _quote_json(shipped, quote)
    header = "invoice %s %s %s" % (shipped.id, shipped.date.isoformat(), shipped.customer)
    return _quote_text(quote, header)


def _fulfil(directory, movements, existing, orders, positionals, date):
    order = _find_order(orders, positionals[0])
    if date < order.date:
        raise Refusal(
            "%s cannot be fulfilled on %s, before its order date %s"
            % (order.id, date.isoformat(), order.date.isoformat())
        )
    results, state = orders_mod.plan_fulfil(order, date, movements)
    added = "".join(
        "%s %s -%d order %s\n" % (date.isoformat(), sku, now, order.id)
        for sku, now, _ in results
        if now > 0
    )
    if added:
        _append(directory, existing, added)
    rows = ["%s shipped %d backordered %d" % row for row in results]
    rows.append("status " + state)
    return _lines(rows)


def _report(catalog, movements, orders, options):
    rows = orders_mod.report_rows(orders, catalog, movements)
    fmt = options["format"]
    if fmt == "json":
        return _dump(
            [
                dict(row, quoted=_amount(row["quoted"]), invoiced=_amount(row["invoiced"]))
                for row in rows
            ]
        )
    if fmt == "csv":
        out = io.StringIO()
        writer = csv.writer(out, lineterminator="\n")
        writer.writerow(
            ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        )
        for r in rows:
            writer.writerow(
                [
                    r["order"], r["date"], r["customer"], r["status"],
                    r["ordered"], r["shipped"], _amount(r["quoted"]), _amount(r["invoiced"]),
                ]
            )
        return out.getvalue()
    return _lines(
        "%s %s %s %s %d/%d %s %s"
        % (
            r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"],
            _amount(r["quoted"]), _amount(r["invoiced"]),
        )
        for r in rows
    )


def _run(argv) -> str:
    command, directory, positionals, options, date = _parse_args(argv)
    directory = "." if directory is None else directory
    if not os.path.isdir(directory):
        raise FileProblem("%s: not a folder" % directory)

    need_movements, need_orders = _FILES[command]
    raw_catalog = _read(directory, CATALOG, True)
    raw_movements = _read(directory, MOVEMENTS, False) if need_movements else b""
    raw_orders = _read(directory, ORDERS, False) if need_orders else b""

    catalog = _parse(CATALOG, parse_catalog, raw_catalog.decode("utf-8"))
    movements = []
    orders = []
    if need_movements:
        movements = _parse(MOVEMENTS, parse_movements, raw_movements.decode("utf-8"), catalog)
    if need_orders:
        orders = _parse(ORDERS, parse_orders, raw_orders.decode("utf-8"), catalog)

    if command == "stock":
        return _stock(catalog, movements, options)
    if command == "low":
        return _low(catalog, movements, options)
    if command == "history":
        return _history(catalog, movements, positionals, options)
    if command in ("receive", "ship"):
        return _move(command, directory, catalog, movements, raw_movements, positionals, date)
    if command == "quote":
        return _quote(catalog, orders, positionals, options)
    if command == "fulfil":
        return _fulfil(directory, movements, raw_movements, orders, positionals, date)
    if command == "invoice":
        return _invoice(catalog, movements, orders, positionals, options)
    return _report(catalog, movements, orders, options)


# --------------------------------------------------------------------- main

def _emit(text: str) -> None:
    out = sys.stdout
    buffer = getattr(out, "buffer", None)
    if buffer is not None:
        out.flush()
        buffer.write(text.encode("utf-8"))
        buffer.flush()
    else:
        out.write(text)
        out.flush()


def _quiet_stdout() -> None:
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _complain(message: str) -> None:
    try:
        sys.stderr.write("stockroom: %s\n" % message)
        sys.stderr.flush()
    except (OSError, ValueError):
        pass


def main(argv=None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        output = _run(list(argv))
    except UsageError as err:
        _complain(str(err))
        try:
            sys.stderr.write(USAGE)
            sys.stderr.flush()
        except (OSError, ValueError):
            pass
        return 2
    except FileProblem as err:
        _complain(str(err))
        return 2
    except Refusal as err:
        _complain(str(err))
        return 1
    if output:
        try:
            _emit(output)
        except BrokenPipeError:
            _quiet_stdout()
    return 0


if __name__ == "__main__":
    sys.exit(main())
